from pathlib import Path
import shutil
p=Path(__file__).resolve().parent;data=p/'fft-data';data.mkdir(exist_ok=True)
for name in ['smoke','normal','large']:shutil.copyfile(p/'fft'/(name+'.values'),data/(name+'.values'))
lines=['structure NeedFft=BenchHartelFftFn(BenchNeed)','structure StrictFft=BenchHartelFftFn(BenchStrict)','structure NeedDriver=BenchHartelFftDriverFn(NeedFft)','structure StrictDriver=BenchHartelFftDriverFn(StrictFft)','structure FftTests =','struct','  structure N=NeedFft','  structure R=StrictFft','  fun number s=case Real.fromString s of SOME x=>x|NONE=>raise Fail "invalid real"','  fun reference profile=','    let val f=TextIO.openIn(profile^".values") val raw=TextIO.inputAll f val _=TextIO.closeIn f','        fun scan([],_,iaa,rll)=(List.rev iaa,List.rev rll)','          |scan(line::rest,section,iaa,rll)=case String.tokens Char.isSpace line of','             ["INPUT"]=>scan(rest,0,iaa,rll)|["IAA"]=>scan(rest,1,iaa,rll)|["RLL"]=>scan(rest,2,iaa,rll)','            |[a,b]=>let val value=(number a,number b)in','               if section=1 then scan(rest,section,value::iaa,rll)','               else if section=2 then scan(rest,section,iaa,value::rll)','               else scan(rest,section,iaa,rll)end','            |_=>raise Fail "invalid reference line"','    in scan(String.tokens(fn c=>c= #"\\n")raw,0,[],[])end','  fun close((a,b),(c,d))=Real.isFinite a andalso Real.isFinite b','    andalso Real.abs(a-c)<=2.0E~7+2.0E~12*Real.abs c','    andalso Real.abs(b-d)<=2.0E~7+2.0E~12*Real.abs d','  fun agrees([],[])=true|agrees(a::xs,b::ys)=close(a,b)andalso agrees(xs,ys)|agrees _=false','  fun needValues xs=case BenchNeed.force xs of N.Nil=>[]|N.Cons(x,xs)=>BenchNeed.force x::needValues xs','  fun strictValues xs=case BenchStrict.force xs of R.Nil=>[]|R.Cons(x,xs)=>BenchStrict.force x::strictValues xs','  fun multiply((a:real,b:real),(c,d))=(a*c-b*d,a*d+b*c)','  fun add((a:real,b:real),(c,d))=(a+c,b+d)','  fun custom n=List.tabulate(n,fn i=>(Real.fromInt((i*17)mod 29-14),Real.fromInt((i*13)mod 19-9)))','  fun dft input=','    let val n=List.length input','    in List.tabulate(n,fn k=>','      let fun sum([],_,acc)=acc|sum(x::xs,j,acc)=','        let val angle=2.0*Math.pi*Real.fromInt(k*j)/Real.fromInt n','        in sum(xs,j+1,add(acc,multiply(x,(Math.cos angle,Math.sin angle))))end','      in sum(input,0,(0.0,0.0))end)end']
for profile,coarse,checksum in [('smoke',1,'14976/128'),('normal',3,'59904/512'),('large',5,'239616/2048')]:
 for mode,k,toList,driver in [('lazy','N','needValues','NeedDriver'),('strict','R','strictValues','StrictDriver')]:
  for method,index in [('arrayMain','#1'),('listMain','#2')]:lines.append(f'  val _=T.check("fft/{mode}-{profile}-{method}-source-values",fn()=>agrees({toList}({k}.{method}({k}.input {coarse})),{index}(reference "{profile}")))')
  lines.append(f'  val _=T.check("fft/{mode}-{profile}-analytic-and-status",fn()=>{k}.run {coarse}({k}.reference {coarse})="{checksum}")')
  wanted=f'2:{checksum}:{2*(len(checksum)+1)}';lines.append(f'  val _=T.check("fft/{mode}-{profile}-repeat",fn()=>{driver}.run["{coarse}","2"]="{wanted}")')
for n in [8,16,32]:
 for mode,k,toList in [('lazy','N','needValues'),('strict','R','strictValues')]:
  for method in ['arrayMain','listMain']:lines.append(f'  val _=T.check("fft/{mode}-nonuniform-{n}-{method}-direct-dft",fn()=>let val input=custom {n} in agrees({toList}({k}.{method}({k}.fromList input)),dft input)end)')
lines+=['  val _=T.check("fft/source-comparison-half-inclusive",fn()=>N.sourceCompare((0.0,0.0),(0.5,~0.5)))','  val _=T.check("fft/source-comparison-half-exceeded",fn()=>not(N.sourceCompare((0.0,0.0),(0.5000001,0.0))))','  val _=T.check("fft/strong-check-rejects-legacy-tolerance-perturbation",fn()=>','    N.sourceCompare((0.0,0.0),(0.1,0.0))andalso((N.checkValue((0.1,0.0),(0.0,0.0));false)handle Fail s=>String.isPrefix "incorrect result:" s))','  val _=T.check("fft/inside-bound",fn()=>(N.checkValue((0.5E~7,~0.5E~7),(0.0,0.0));true))']
for label,value in [('outside-bound','(2.0E~7,0.0)'),('nan','(0.0/0.0,0.0)'),('infinity','(1.0/0.0,0.0)')]:lines.append(f'  val _=T.check("fft/reject-{label}",fn()=>((N.checkValue({value},(0.0,0.0));false)handle Fail s=>String.isPrefix "incorrect result:" s))')
lines+=['  val _=T.check("fft/input-copies-share-complex-cell",fn()=>','    let val input=N.input 1 fun nth xs 0=(case BenchNeed.force xs of N.Cons(x,_)=>x|_=>raise Empty)','          |nth xs n=(case BenchNeed.force xs of N.Cons(_,rest)=>nth rest(n-1)|_=>raise Empty)','    in nth input 0=nth input 64 end)','  val _=T.check("fft/numerical-input-head-is-memoized",fn()=>','    let val count=ref 0 val value=BenchNeed.delay(fn()=>(count:= !count+1;(3.0,4.0)))','        val source=BenchNeed.delay(fn()=>N.Cons(value,N.empty()))','        val _=needValues(N.arrayMain source) val _=needValues(N.listMain source)','    in !count=1 end)','end']
(p/'fft-tests.sml').write_text('\n'.join(lines)+'\n');(p/'fft-test-data.txt').write_text(''.join(f.name+'\n'for f in sorted(data.iterdir())if f.suffix=='.values'));root=Path.cwd();files=['tests/basis/harness.sml','examples/benchmarks/shared/input.sml','examples/benchmarks/shared/lazy.sml','examples/benchmarks/shared/suspend.sml',str(p/'fft.sml'),str(p/'fft-driver.sml'),str(p/'fft-tests.sml'),'tests/basis/finish.sml'];(p/'fft-test-sources.txt').write_text(''.join(str(root/f)+'\n'for f in files))
